--
-- `cargo xtask legacy-import --check` regenerates into a temporary directory and
-- diffs, so a hand edit here is a build failure rather than a surviving change.
-- The procedure these files implement is docs/data-migration.md.

-- Staging and the column inventory. Runs on the TARGET (new) database. Nothing in
-- the migration ever writes to the source: it is read-only for the duration
-- (docs/data-migration.md Decision 3), which is also why the source's column list
-- has to be carried over rather than queried through a foreign table.

CREATE SCHEMA IF NOT EXISTS w9;

COMMENT ON SCHEMA w9 IS
    'One-time Go-to-Rust migration staging (W9). Droppable once
     docs/data-migration.md reconciliation passes and the source is decommissioned;
     observations_1d_legacy is NOT in here and is not droppable.';

