-- ------------------------------------------------------------------
-- 2. What the source actually has. Populated by migrate-from-go.sh from a
--    read-only query against the old database; see w9.source_inventory_query().
--    Production declares ~143 of the 215 columns the Go source defines and nothing
--    in the repository knows which 143 (W0 OQ-6), so this is data, not a constant.
-- ------------------------------------------------------------------

CREATE TABLE w9.source_column (
    column_name text PRIMARY KEY,
    data_type   text NOT NULL,
    ordinal     int  NOT NULL
);

CREATE FUNCTION w9.source_inventory_query() RETURNS text
LANGUAGE sql IMMUTABLE AS $fn$
    SELECT $q$COPY (SELECT column_name, udt_name, ordinal_position
                      FROM information_schema.columns
                     WHERE table_schema = 'public' AND table_name = 'weather'
                     ORDER BY ordinal_position) TO STDOUT (FORMAT csv)$q$
$fn$;

COMMENT ON FUNCTION w9.source_inventory_query() IS
    'The read-only statement to run on the OLD database. Its output loads into
     w9.source_column. It reads a catalogue view and writes nothing.';

-- The gap report. Three classes, and only one of them is benign.
--
--   missing_in_source  the registry declares it, production does not have it. The
--                      column imports as NULL. Expected for ~72 columns (OQ-6) and
--                      harmless: a NULL costs one bit (D-3). Report the count.
--   unknown_in_source  production has a column the registry has never heard of.
--                      This is NOT benign — it is data with no destination, and it
--                      has to become a [[metric]] entry, go into `extra`, or be
--                      consciously dropped, BEFORE the import runs.
--   type_mismatch      both sides have it and disagree on the type.
CREATE VIEW w9.gap_report AS
SELECT coalesce(e.column_name, s.column_name) AS column_name,
       e.sql_type   AS expected_type,
       s.data_type  AS source_type,
       e.kind,
       CASE WHEN s.column_name IS NULL THEN 'missing_in_source'
            WHEN e.column_name IS NULL THEN 'unknown_in_source'
            WHEN e.sql_type <> s.data_type THEN 'type_mismatch'
            ELSE 'ok' END AS verdict
  FROM w9.expected_column e
  FULL OUTER JOIN w9.source_column s USING (column_name);

-- The third class has one legitimate resolution besides modelling it: decide, on
-- the record, not to carry it. That decision belongs in the database rather than
-- in a shell history, because the alternative to writing it down is deleting a row
-- from w9.source_column, which leaves no trace that it was deliberate.
CREATE TABLE w9.dropped_source_column (
    column_name text PRIMARY KEY,
    reason      text NOT NULL,
    decided_at  timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE w9.dropped_source_column IS
    'Source columns consciously not carried over. Every row is a decision someone
     made; `reason` is not optional for that reason.';

-- Fails the migration rather than importing into a column nobody chose.
CREATE FUNCTION w9.assert_no_unknown_source_columns() RETURNS void
LANGUAGE plpgsql AS $fn$
DECLARE bad text;
BEGIN
    SELECT string_agg(g.column_name || ' ' || g.source_type, ', ' ORDER BY g.column_name)
      INTO bad
      FROM w9.gap_report g
      LEFT JOIN w9.dropped_source_column d USING (column_name)
     WHERE g.verdict = 'unknown_in_source' AND d.column_name IS NULL;
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'the source has columns with no registry entry: %', bad
            USING HINT = 'add a [[metric]] entry, route it to observations.extra, '
                         'or INSERT it into w9.dropped_source_column with a reason';
    END IF;
END $fn$;

-- ------------------------------------------------------------------
-- 3. stationname -> station_id. The one mapping a human has to supply.
-- ------------------------------------------------------------------
--
-- The old table keys readings by station *name* and the new one by `station_id`
-- (W4 2.1). `/span?station=<device name>` is frozen and matches the name, so the
-- safe default is station_id = stationname: it keeps every historical row
-- addressable by the parameter both shipped clients already send. Choosing
-- something else is allowed and means the history is reachable only under the new
-- id, which is why this table is populated by hand and asserted non-empty rather
-- than defaulted silently.

CREATE TABLE w9.station_map (
    stationname           text PRIMARY KEY,
    station_id            text NOT NULL UNIQUE,
    stationtype           text,
    timezone              text NOT NULL DEFAULT 'UTC',
    latitude              double precision,
    longitude             double precision,
    altitude_ft           double precision,
    snow_base_distance_mm double precision
);

-- The names actually present in the source, so the map can be checked for
-- completeness before 19 GB moves. Loaded by migrate-from-go.sh.
CREATE TABLE w9.source_station (
    stationname text PRIMARY KEY,
    stationtype text,
    first_seen  timestamptz,
    last_seen   timestamptz,
    rows        bigint
);

CREATE FUNCTION w9.source_station_query() RETURNS text
LANGUAGE sql IMMUTABLE AS $fn$
    SELECT $q$COPY (SELECT stationname, min(stationtype), min(time), max(time), count(*)
                      FROM weather GROUP BY stationname ORDER BY stationname)
              TO STDOUT (FORMAT csv)$q$
$fn$;

CREATE FUNCTION w9.assert_station_map_complete() RETURNS void
LANGUAGE plpgsql AS $fn$
DECLARE bad text;
BEGIN
    SELECT string_agg(s.stationname, ', ' ORDER BY s.stationname) INTO bad
      FROM w9.source_station s
      LEFT JOIN w9.station_map m USING (stationname)
     WHERE m.stationname IS NULL;
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'w9.station_map has no entry for: %', bad
            USING HINT = 'INSERT INTO w9.station_map (stationname, station_id, stationtype) '
                         'SELECT stationname, stationname, stationtype FROM w9.source_station '
                         'adopts the frozen-contract-preserving default';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM w9.source_station) THEN
        RAISE EXCEPTION 'w9.source_station is empty; load it before asserting'
            USING HINT = 'migrate-from-go.sh inventory';
    END IF;
END $fn$;

