-- The old views have no uniqueness constraint on (bucket, stationname) — a
-- materialisation hypertable does not carry one — so the archive copy can in
-- principle arrive with duplicates. Assert rather than assume: a duplicated bucket
-- would double a daily rainfall total and halve nothing, which no reconciliation
-- below would flag as a type error.
CREATE FUNCTION w9.assert_archive_unique(level text) RETURNS void
LANGUAGE plpgsql AS $fn$
DECLARE n bigint;
BEGIN
    EXECUTE format('SELECT count(*) FROM (SELECT bucket, stationname FROM
                    w9.weather_%s_archive GROUP BY 1,2 HAVING count(*) > 1) d', level)
      INTO n;
    IF n > 0 THEN
        RAISE EXCEPTION 'w9.weather_%_archive has % duplicated (bucket, stationname) pairs',
            level, n;
    END IF;
END $fn$;
